<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use Pterodactyl\Models\User; use Illuminate\Support\Collection; use Pterodactyl\Models\Egg; use Pterodactyl\Models\Server; class Servers { public const PREFERENCE = 'discordHiddenServers'; public const MAX_LISTED = 200; public static function hidden(User $user): array { $stored = $user->dezerx_preferences[self::PREFERENCE] ?? []; return is_array($stored) ? array_values(array_filter(array_map('strval', $stored), fn (string $uuid) => $uuid !== '')) : []; } public static function reachable(User $user, int $limit = self::MAX_LISTED): Collection { $scope = BotConfig::scope(); return Server::query() ->with('egg') ->whereIn('id', $user->accessibleServers()->pluck('id')) ->when($scope['eggs'] !== [], fn ($builder) => $builder->whereIn('egg_id', Egg::query()->whereIn('uuid', $scope['eggs'])->pluck('id'))) ->when($scope['nodes'] !== [], fn ($builder) => $builder->whereIn('node_id', $scope['nodes'])) ->orderBy('name') ->limit($limit) ->get(); } public static function list(ClientApi $api): array { $servers = []; $hidden = self::hidden($api->user()); for ($page = 1; $page <= 4; ++$page) { $response = $api->get('', ['include' => 'egg', 'per_page' => 100, 'page' => $page]); if (!$response->ok()) { return $page === 1 ? ['error' => $response->error(), 'servers' => []] : ['error' => null, 'servers' => $servers]; } foreach ((array) ($response->body['data'] ?? []) as $row) { if (!is_array($row)) { continue; } $server = self::normalise($row); if (BotConfig::covers($server['egg']['uuid'] ?: null, $server['node_id']) && !in_array($server['uuid'], $hidden, true)) { $servers[] = $server; } } if ($page >= (int) $response->meta('pagination.total_pages', 1)) { break; } } return ['error' => null, 'servers' => $servers]; } public static function find(ClientApi $api, string $identifier): array { if (preg_match('/^[a-z0-9-]{8,36}$/i', $identifier) !== 1) { return ['error' => 'Pick a server from the list as you type.', 'server' => null]; } $response = $api->get('servers/' . $identifier, ['include' => 'egg']); if (!$response->ok()) { return ['error' => $response->error(), 'server' => null]; } $server = self::normalise((array) $response->body); if (!BotConfig::covers($server['egg']['uuid'] ?: null, $server['node_id']) || in_array($server['uuid'], self::hidden($api->user()), true)) { return ['error' => 'The Discord bot is not available for this server.', 'server' => null]; } return ['error' => null, 'server' => $server]; } public static function resources(ClientApi $api, array $server): array { $response = $api->get('servers/' . $server['id'] . '/resources'); if (!$response->ok()) { return ['state' => self::fallbackState($server), 'error' => $response->error(), 'usage' => null]; } $attributes = $response->attributes(); $usage = (array) ($attributes['resources'] ?? []); return [ 'state' => self::state($server, (string) ($attributes['current_state'] ?? 'offline'), (bool) ($attributes['is_suspended'] ?? false)), 'error' => null, 'usage' => [ 'memory' => (int) ($usage['memory_bytes'] ?? 0), 'cpu' => (float) ($usage['cpu_absolute'] ?? 0), 'disk' => (int) ($usage['disk_bytes'] ?? 0), 'rx' => (int) ($usage['network_rx_bytes'] ?? 0), 'tx' => (int) ($usage['network_tx_bytes'] ?? 0), 'uptime' => (int) ($usage['uptime'] ?? 0), ], ]; } public static function percentages(array $server, ?array $usage): array { if ($usage === null) { return ['cpu' => null, 'memory' => null, 'disk' => null]; } $limits = $server['limits']; return [ 'cpu' => $limits['cpu'] > 0 ? $usage['cpu'] / $limits['cpu'] * 100 : null, 'memory' => $limits['memory'] > 0 ? $usage['memory'] / ($limits['memory'] * 1048576) * 100 : null, 'disk' => $limits['disk'] > 0 ? $usage['disk'] / ($limits['disk'] * 1048576) * 100 : null, ]; } public static function primaryAddress(array $server): string { foreach ($server['allocations'] as $allocation) { if ($allocation['is_default']) { return Format::address($allocation); } } return isset($server['allocations'][0]) ? Format::address($server['allocations'][0]) : ''; } public static function panelUrl(array $server, string $tab = ''): string { return BotConfig::panelUrl('server/' . $server['id'] . ($tab === '' ? '' : '/' . ltrim($tab, '/'))); } public static function normalise(array $row): array { $attributes = (array) ($row['attributes'] ?? $row); $relationships = (array) ($attributes['relationships'] ?? []); $egg = (array) ($relationships['egg']['attributes'] ?? []); $allocations = []; foreach ((array) ($relationships['allocations']['data'] ?? []) as $allocation) { $allocation = (array) ($allocation['attributes'] ?? []); $allocations[] = [ 'id' => (int) ($allocation['id'] ?? 0), 'ip' => (string) ($allocation['ip'] ?? ''), 'ip_alias' => (string) ($allocation['ip_alias'] ?? ''), 'port' => (int) ($allocation['port'] ?? 0), 'notes' => (string) ($allocation['notes'] ?? ''), 'is_default' => (bool) ($allocation['is_default'] ?? false), ]; } $limits = (array) ($attributes['limits'] ?? []); $features = (array) ($attributes['feature_limits'] ?? []); return [ 'id' => (string) ($attributes['identifier'] ?? ''), 'uuid' => (string) ($attributes['uuid'] ?? ''), 'name' => (string) ($attributes['name'] ?? 'Server'), 'description' => (string) ($attributes['description'] ?? ''), 'node' => (string) ($attributes['node'] ?? ''), 'node_id' => (int) ($attributes['node_id'] ?? 0), 'owner' => (bool) ($attributes['server_owner'] ?? false), 'status' => $attributes['status'] ?? null, 'suspended' => (bool) ($attributes['is_suspended'] ?? false), 'installing' => (bool) ($attributes['is_installing'] ?? false), 'transferring' => (bool) ($attributes['is_transferring'] ?? false), 'limits' => [ 'memory' => (int) ($limits['memory'] ?? 0), 'disk' => (int) ($limits['disk'] ?? 0), 'cpu' => (int) ($limits['cpu'] ?? 0), ], 'backup_limit' => (int) ($features['backups'] ?? 0), 'egg' => [ 'uuid' => (string) ($egg['uuid'] ?? ''), 'name' => (string) ($egg['name'] ?? ''), ], 'allocations' => $allocations, 'sftp' => [ 'ip' => (string) ($attributes['sftp_details']['ip'] ?? ''), 'port' => (int) ($attributes['sftp_details']['port'] ?? 2022), ], ]; } public static function logo(array $server): ?string { return Art::logo($server['egg']['uuid'] ?: null, $server['egg']['name'] ?: null); } public static function banner(array $server): ?string { return Art::banner($server['egg']['uuid'] ?: null, $server['egg']['name'] ?: null); } private static function state(array $server, string $current, bool $suspended): string { if ($suspended || $server['suspended'] || $server['status'] === 'suspended') { return 'suspended'; } if ($server['transferring']) { return 'transferring'; } if (in_array($server['status'], ['installing', 'install_failed', 'reinstall_failed', 'restoring_backup'], true)) { return (string) $server['status']; } return array_key_exists($current, Format::STATES) ? $current : 'offline'; } private static function fallbackState(array $server): string { return self::state($server, 'unknown', false); } } 